        $this->logDebug("Count for Template asset on adapter ");
        $span = $this->startSpan("Count for Template asset on adapter");
        try {
            $original = $ref instanceof TemplateAsset ? $ref : $this->retrieveForUpdate(new TemplateAssetFilter(uids: [$ref->uid()]));
            $prevContent = $original?->getContent();
            $currContent = $entity->getContent();
            if ($prevContent != $currContent) {
                if (null !== $prevContent) {
                    $this->store->deleteFile(new FileStoreKey($prevContent));
                }
                $entity->commitContentWith($this->store);
            }
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('template-asset', $entity->uid() ?? 'no-id', $entity->asPublicJson());
